DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='search_business_identities';IF position('WHERE w.account_type IN' IN def)=0 THEN RAISE EXCEPTION 'Discovery definition changed';END IF;def:=replace(def,'WHERE w.account_type IN','WHERE (w.provider_subtype<>''independent_contractor'' OR coalesce((public.contractor_evidence_summary(w.id)->>''discoverable'')::boolean,false)) AND w.account_type IN');EXECUTE def;END $$;
CREATE FUNCTION public.contractor_hold_scope(_ws uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR (public.admin_can('people','manage') AND public.admin_can_account(_ws)) $$;
REVOKE ALL ON FUNCTION public.contractor_hold_scope(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_hold_scope(uuid) TO authenticated,service_role;
CREATE FUNCTION public.contractor_documented_hold(_ws uuid,_hold boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid;BEGIN IF NOT public.contractor_hold_scope(_ws) OR length(btrim(_reason)) NOT BETWEEN 5 AND 500 OR NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_ws AND provider_subtype='independent_contractor' AND NOT is_test_account) THEN RAISE EXCEPTION 'Authorized scoped administrator and documented reason required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(_ws::text,74));INSERT INTO public.contractor_safety_events(workspace_id,hold,reason,actor_id) VALUES(_ws,_hold,btrim(_reason),auth.uid()) RETURNING id INTO rid;INSERT INTO public.account_security_audit(user_id,sender_mfn_id,workspace_id,event_type,result) VALUES(auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),_ws,'contractor_safety_hold',jsonb_build_object('event_id',rid,'hold',_hold));END $$;
REVOKE ALL ON FUNCTION public.contractor_documented_hold(uuid,boolean,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_documented_hold(uuid,boolean,text) TO authenticated,service_role;
CREATE FUNCTION public.contractor_evidence_access(_ws uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND m.role='owner' AND m.removed_at IS NULL AND NOT m.is_contractor AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL AND w.status='active' AND NOT w.is_test_account) $$;
CREATE POLICY contractor_private_all_evidence ON public.provider_credentials AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=workspace_id AND provider_subtype='independent_contractor') OR provider_user_id=auth.uid());
CREATE FUNCTION public.contractor_listing_entitlement_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.provider_subtype='independent_contractor' AND (TG_OP='INSERT' OR NEW.contractor_intake_progress IS DISTINCT FROM OLD.contractor_intake_progress) AND NEW.contractor_intake_progress IS NOT NULL AND (jsonb_typeof(NEW.contractor_intake_progress)<>'object' OR NOT ((NEW.contractor_intake_progress->>'step')::int BETWEEN 0 AND 6)) THEN RAISE EXCEPTION 'Invalid contractor intake progress';END IF;RETURN NEW;END $$;
CREATE TRIGGER contractor_progress_validation BEFORE INSERT OR UPDATE ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.contractor_listing_entitlement_guard();